    merged_any = True
    while merged_any:
        merged_any = False
        for _, i, j in pairs:
            ri = route_of.get(i, -1)
            rj = route_of.get(j, -1)
            if ri == -1 or rj == -1 or ri == rj:
                continue
            if not active[ri] or not active[rj]:
                continue

            rt_i = routes[ri]
            rt_j = routes[rj]

            # Reorient whole routes to support i -> j concatenation whenever possible.
            # Deterministic: only reverse whole routes, never partial.
            rt_i2, ok_i = orient_route_to_make_node_at_end(rt_i, i)
            if not ok_i:
                continue
            if rt_i2 is not rt_i:
                routes[ri] = rt_i2
                rt_i = routes[ri]

            rt_j2, ok_j = orient_route_to_make_node_at_start(rt_j, j)
            if not ok_j:
                continue
            if rt_j2 is not rt_j:
                routes[rj] = rt_j2
                rt_j = routes[rj]

            # Now merge is valid if i at end and j at start
            if rt_i and rt_i[-1] == i and rt_j and rt_j[0] == j:
                if load[ri] + load[rj] <= capacity:
                    routes[ri] = rt_i + rt_j
                    load[ri] = load[ri] + load[rj]
                    active[rj] = False
                    for x in rt_j:
                        route_of[x] = ri
                    merged_any = True

    routes = [routes[i] for i in range(len(routes)) if active[i]]
    load = [route_load(rt) for rt in routes]

    # --- Repair / reinsertion if any customer got lost (safety) ---
    present = set()
    for rt in routes:
        for x in rt:
            present.add(x)
    missing = [c for c in customers if c not in present]
    if missing:
        for c in missing:
            best_r = None
            best_pos = None
            best_delta = None
            for rid, rt in enumerate(routes):
                if load[rid] + demands[c] > capacity:
                    continue
                L = len(rt)
                best_here_delta = None
                best_here_pos = None
                for pos in range(L + 1):
                    delta = cost_with_insertion(rt, pos, c)
                    if best_here_delta is None or delta < best_here_delta or (delta == best_here_delta and (best_here_pos is None or pos < best_here_pos)):
                        best_here_delta = delta
                        best_here_pos = pos
                if best_here_delta is not None:
                    if best_delta is None or best_here_delta < best_delta or (best_here_delta == best_delta and rid < best_r):
                        best_delta = best_here_delta
                        best_r = rid
                        best_pos = best_here_pos
            if best_r is None:
                routes.append([c])
                load.append(demands[c])
            else:
                routes[best_r].insert(best_pos, c)
                load[best_r] += demands[c]

    # --- Deterministic local search: inter-route relocate and intra-route 2-opt ---
    max_outer = 200
    max_reloc = 600
    moved = True
    outer = 0

    def build_route_index(routes_local):
        idx = {}
        for r, rt in enumerate(routes_local):
            for k in rt:
                idx[k] = r
        return idx

    while moved and outer < max_outer:
        outer += 1
        moved = False

        r_index = build_route_index(routes)
        base_costs = [route_cost(rt) for rt in routes]
        best_move = None  # (delta, from_r, from_pos, to_r, to_pos)

        reloc_checks = 0
        for from_r, rt in enumerate(routes):
            if not rt:
                continue
            Lfrom = len(rt)
            for from_pos, node in enumerate(rt):
                reloc_checks += 1
                if reloc_checks > max_reloc:
                    break

                if len(rt) == 1:
                    rem_delta = -(matrix[depot][node] + matrix[node][depot])
                else:
                    prev = depot if from_pos == 0 else rt[from_pos - 1]
                    nxt = depot if from_pos == len(rt) - 1 else rt[from_pos + 1]
                    rem_delta = matrix[prev][nxt] - (matrix[prev][node] + matrix[node][nxt])

                for to_r, to_rt in enumerate(routes):
                    if to_r == from_r:
                        continue
                    if load[to_r] + demands[node] > capacity:
                        continue
                    L = len(to_rt)
                    best_here_pos = None
                    best_here_delta = None
                    for to_pos in range(L + 1):
                        ins_delta = cost_with_insertion(to_rt, to_pos, node)
                        total_delta = ins_delta + rem_delta
                        if best_here_delta is None or total_delta < best_here_delta or (total_delta == best_here_delta and to_pos < best_here_pos):
                            best_here_delta = total_delta
                            best_here_pos = to_pos
                    if best_here_delta is not None:
                        if best_move is None or best_here_delta < best_move[0] or (best_here_delta == best_move[0] and (from_r, from_pos, to_r, best_here_pos) < (best_move[1], best_move[2], best_move[3], best_move[4])):
                            best_move = (best_here_delta, from_r, from_pos, to_r, best_here_pos)

                if reloc_checks > max_reloc:
                    break
            if reloc_checks > max_reloc:
                break

        if best_move is not None and best_move[0] < 0:
            _, from_r, from_pos, to_r, to_pos = best_move
            node = routes[from_r][from_pos]
            routes[from_r].pop(from_pos)
            load[from_r] -= demands[node]
            routes[to_r].insert(to_pos, node)
            load[to_r] += demands[node]
            moved = True
            if not routes[from_r]:
                routes.pop(from_r)
                load.pop(from_r)
            continue

        # Intra-route 2-opt (first-improvement across routes deterministically)
        moved = False
        base_costs = [route_cost(rt) for rt in routes]
        for r, rt in enumerate(routes):
            L = len(rt)
            if L < 4:
                continue
            improved = False
            for i in range(L - 3):
                a = rt[i]
                b = rt[i + 1]
                for k in range(i + 2, L - 1):
                    c = rt[k]
                    d = rt[k + 1]
                    delta = (matrix[a][c] + matrix[b][d]) - (matrix[a][b] + matrix[c][d])
                    if delta < 0:
                        routes[r] = rt[:i + 1] + rt[i + 1:k + 1][::-1] + rt[k + 1:]
                        load[r] = route_load(routes[r])
                        moved = True
                        improved = True
                        break
                if improved:
                    break
            if moved:
                break

    routes = [rt for rt in routes if rt]
    return routes
